import React, { useState, useEffect, useContext } from 'react';
import { UserContext } from './UserContext';
import './CartPage.css';

const CartPage = () => {
  const { userId } = useContext(UserContext); // Access userId from context
  const [items, setItems] = useState([]); // State to store cart items with full product details
  const [message, setMessage] = useState('');

  useEffect(() => {
    if (userId) {
      fetchCartItems();
    }
  }, [userId]);

  // Fetch cart items from API
  const fetchCartData = async () => {
    try {
      const response = await fetch(`/api/user?userId=${userId}`);
  
      // Log the status code and response text for debugging
      const responseText = await response.text();
      console.log('Response Status:', response.status);
      console.log('Response Text:', responseText); // This will show the raw HTML or error message
  
      if (!response.ok) {
        throw new Error(`Failed to fetch data: ${response.status}`);
      }
  
      // Assuming the response is expected to be JSON, we parse it here
      const data = JSON.parse(responseText);
      setItems(data.cart || []); // Set cart items to state
    } catch (error) {
      console.error('Error fetching cart:', error);
    }
  };
  

  // Fetch items from a specific collection (Inventory or Jewellery)
  const fetchItemsFromCollection = async (cartItems, collection) => {
    const ids = cartItems
      .filter(item => item.itemId.collection === collection)
      .map(item => item.itemId._id);
      
    const collectionData = await Promise.all(
      ids.map(id => fetch(`/api/${collection}/${id}`).then(res => res.json()))
    );

    return cartItems
      .filter(item => item.itemId.collection === collection)
      .map((item, index) => ({
        ...item,
        product: collectionData[index], // Attach product details to cart item
      }));
  };

  const incrementQuantity = (id) => {
    setItems(items.map(item => 
      item._id === id ? { ...item, quantity: item.quantity + 1 } : item
    ));
  };

  const decrementQuantity = (id) => {
    setItems(items.map(item => {
      if (item._id === id && item.quantity > 1) {
        return { ...item, quantity: item.quantity - 1 };
      }
      return item;
    }));
  };

  const subtotal = items.reduce((total, item) => total + (item.product.price * item.quantity), 0);

  return (
    <div className="cart-container">
      <div className="cart-items">
        <h2>MY CART</h2>
        {items.length === 0 ? (
          <p>Your cart is empty.</p>
        ) : (
          items.map(item => (
            <div key={item._id} className="cart-item">
              <img src={item.product.images[0]} alt={item.product.name} className="cart-item-image" />
              <div className="cart-item-details">
                <h3>{item.product.name}</h3>
                <p>Price: ₹{item.product.price}</p>
                <div className="cart-item-quantity">
                  <button onClick={() => decrementQuantity(item._id)}>-</button>
                  <span>{item.quantity}</span>
                  <button onClick={() => incrementQuantity(item._id)}>+</button>
                </div>
                <button className="remove-item" onClick={() => decrementQuantity(item._id)}>Remove</button>
              </div>
            </div>
          ))
        )}
      </div>
      {message && <p className="message">{message}</p>}
      
      {items.length > 0 && (
        <div className="cart-subtotal">
          <h2>CART SUBTOTAL</h2>
          {items.map(item => (
            <div key={item._id} className="subtotal-item">
              <img src={item.product.images[0]} alt={item.product.name} className="subtotal-image" />
              <div className="subtotal-details">
                <p>{item.product.name}</p>
                <p>X{item.quantity}</p>
                <p>₹{item.product.price * item.quantity}</p>
              </div>
            </div>
          ))}
          <div className="total">SUBTOTAL: ₹{subtotal}</div>
          <button className="checkout-button">Checkout</button>
        </div>
      )}
    </div>
  );
};

export default CartPage;
